//! The kopia flag-coverage ratchet (#708): every flag kopia's help lists for a
//! command Kopiur runs has a reviewed `FlagDisposition`, and every reviewed entry
//! still names a real kopia flag and a real CRD field.
//!
//! Hermetic: the kopia side is the help snapshots under
//! `tests/fixtures/kopia-flags/` (regenerated by `cargo xtask gen-kopia-flags`,
//! part of `mise run gen`; `mise run gen-check` fails when they are stale for the
//! pinned kopia), the CRD side is the generated YAML under `deploy/crds/`. When a
//! kopia bump adds a flag, regenerating makes test (a) below name it; classify it
//! in `crates/api/src/kopia_flags/table.rs`.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use kopiur_api::kopia_flags::{
    Arity, FlagDisposition, FlagSpec, GLOBAL_FLAGS, KopiaCommand, StorageBackend,
};

fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn fixture_dir() -> PathBuf {
    crate_dir().join("tests/fixtures/kopia-flags")
}

/// One fixture line, normalized: `name` → (`arity`, `short`).
type Snapshot = BTreeMap<String, (Arity, Option<char>)>;

fn read_fixture(file: &str) -> Snapshot {
    let path = fixture_dir().join(file);
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "{}: {e}. Fix: run `mise run gen` to snapshot kopia's help for this command",
            path.display()
        )
    });
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|line| {
            let (short, rest) = match line.strip_prefix('-') {
                Some(after) if !after.starts_with('-') => {
                    let c = after.chars().next().expect("short flag");
                    (
                        Some(c),
                        after[1..].strip_prefix(", ").expect("`-x, --name`"),
                    )
                }
                _ => (None, line),
            };
            let rest = rest.strip_prefix("--").expect("flag line starts with --");
            match rest.strip_prefix("[no-]") {
                Some(name) => (name.to_string(), (Arity::Bool, short)),
                None => (
                    rest.strip_suffix("=V")
                        .expect("valued flag ends =V")
                        .to_string(),
                    (Arity::Value, short),
                ),
            }
        })
        .collect()
}

/// A fixture, the tables that must cover it exactly, and a label for messages.
struct Coverage {
    label: String,
    fixture: String,
    tables: Vec<&'static [FlagSpec]>,
}

fn coverages() -> Vec<Coverage> {
    let mut out = vec![Coverage {
        label: "every kopia command (global flags)".into(),
        fixture: "global.txt".into(),
        tables: vec![GLOBAL_FLAGS],
    }];
    for cmd in KopiaCommand::ALL {
        out.push(Coverage {
            label: cmd.display(),
            fixture: cmd.fixture_name(),
            tables: cmd.flag_tables().to_vec(),
        });
    }
    for b in StorageBackend::ALL {
        out.push(Coverage {
            label: format!("kopia repository connect {} (storage flags)", b.argv_name()),
            fixture: b.fixture_name(),
            tables: vec![b.flags()],
        });
    }
    out
}

/// (a) No flag kopia lists goes unreviewed, and the table records it with the
/// same arity and alias kopia has (the escape-hatch parser depends on both).
#[test]
fn every_kopia_flag_has_a_reviewed_disposition() {
    let mut missing = Vec::new();
    for c in coverages() {
        let snap = read_fixture(&c.fixture);
        for (name, (arity, short)) in &snap {
            match c
                .tables
                .iter()
                .flat_map(|t| t.iter())
                .find(|f| f.name == name)
            {
                None => missing.push(format!(
                    "`--{name}` on `{}` has no entry. Fix: classify it in \
                     crates/api/src/kopia_flags/table.rs (Modeled / OwnedByKopiur / Global / \
                     Rejected / Unmodeled, with the reason)",
                    c.label
                )),
                Some(f) if f.arity != *arity || f.short != *short => missing.push(format!(
                    "`--{name}` on `{}`: kopia says arity {arity:?} alias {short:?}, the table \
                     says {:?} / {:?}. Fix: correct the entry",
                    c.label, f.arity, f.short
                )),
                Some(_) => {}
            }
        }
    }
    assert!(missing.is_empty(), "\n{}", missing.join("\n"));
}

/// (b) No entry names a flag kopia no longer has — on ANY command sharing the
/// table, so a shared table cannot keep a flag one of its commands lost.
#[test]
fn every_reviewed_flag_still_exists_in_kopia() {
    let mut stale = Vec::new();
    for c in coverages() {
        let snap = read_fixture(&c.fixture);
        for f in c.tables.iter().flat_map(|t| t.iter()) {
            if !snap.contains_key(f.name) {
                stale.push(format!(
                    "`--{}` is in the table for `{}` but kopia's help ({}) no longer lists it. \
                     Fix: delete the entry (and whatever passes the flag)",
                    f.name, c.label, c.fixture
                ));
            }
        }
    }
    assert!(stale.is_empty(), "\n{}", stale.join("\n"));
}

/// One flag, one decision per command.
#[test]
fn no_flag_is_classified_twice_for_one_command() {
    for c in coverages() {
        let mut seen = BTreeSet::new();
        for f in c.tables.iter().flat_map(|t| t.iter()) {
            assert!(seen.insert(f.name), "`--{}` twice on `{}`", f.name, c.label);
        }
    }
    let mut seen = BTreeSet::new();
    for f in GLOBAL_FLAGS {
        assert!(seen.insert(f.name), "global `--{}` twice", f.name);
    }
}

/// Every fixture file belongs to a command (no stale snapshot of a command
/// Kopiur stopped invoking) and every command has one.
#[test]
fn fixture_set_matches_the_command_list() {
    let expected: BTreeSet<String> = coverages().into_iter().map(|c| c.fixture).collect();
    let actual: BTreeSet<String> = std::fs::read_dir(fixture_dir())
        .expect("fixture dir")
        .map(|e| e.expect("entry").file_name().to_string_lossy().into_owned())
        .collect();
    assert_eq!(
        actual, expected,
        "Fix: run `mise run gen`, and delete snapshots of commands no longer in KopiaCommand::ALL"
    );
}

// --- (c) Modeled / use_instead paths exist in the generated CRDs -------------

fn crd_schemas() -> BTreeMap<String, serde_json::Value> {
    let dir = crate_dir().join("../../deploy/crds");
    let mut out = BTreeMap::new();
    for entry in std::fs::read_dir(&dir).expect("deploy/crds") {
        let path = entry.expect("entry").path();
        if path.file_name().is_some_and(|n| n == "all-crds.yaml") {
            continue;
        }
        let text = std::fs::read_to_string(&path).expect("crd yaml");
        let doc: serde_json::Value = serde_saphyr::from_str(&text).expect("crd parses");
        let kind = doc["spec"]["names"]["kind"]
            .as_str()
            .expect("kind")
            .to_string();
        let schema = doc["spec"]["versions"][0]["schema"]["openAPIV3Schema"].clone();
        out.insert(kind, schema);
    }
    out
}

/// Resolve `spec.a.b[].c` in an openAPIV3 schema.
fn resolve<'a>(
    mut node: &'a serde_json::Value,
    path: &str,
) -> Result<&'a serde_json::Value, String> {
    for seg in path.split('.') {
        let (name, array) = match seg.strip_suffix("[]") {
            Some(n) => (n, true),
            None => (seg, false),
        };
        node = node
            .get("properties")
            .and_then(|p| p.get(name))
            .ok_or_else(|| format!("no `{name}`"))?;
        if array {
            node = node
                .get("items")
                .ok_or_else(|| format!("`{name}` is not an array"))?;
        }
    }
    Ok(node)
}

fn spec_paths() -> Vec<(String, &'static str)> {
    let mut out = Vec::new();
    for c in coverages() {
        for f in c.tables.iter().flat_map(|t| t.iter()) {
            match f.disposition {
                FlagDisposition::Modeled { spec_path } => {
                    out.push((
                        format!("`--{}` on `{}` (Modeled)", f.name, c.label),
                        spec_path,
                    ));
                }
                FlagDisposition::Rejected {
                    use_instead: Some(p),
                    ..
                } => out.push((format!("`--{}` on `{}` (use_instead)", f.name, c.label), p)),
                FlagDisposition::Rejected {
                    use_instead: None, ..
                }
                | FlagDisposition::OwnedByKopiur { .. }
                | FlagDisposition::Global { .. }
                | FlagDisposition::Unmodeled { .. } => {}
            }
        }
    }
    out
}

#[test]
fn every_named_field_exists_in_the_generated_crds() {
    let schemas = crd_schemas();
    let mut bad = Vec::new();
    for (who, spec_path) in spec_paths() {
        let Some((kind, path)) = spec_path.split_once(':') else {
            bad.push(format!("{who}: `{spec_path}` is not `Kind:spec.path`"));
            continue;
        };
        if !path.starts_with("spec.") {
            bad.push(format!("{who}: `{spec_path}` must point under `spec.`"));
            continue;
        }
        match schemas.get(kind) {
            None => bad.push(format!("{who}: no CRD of kind `{kind}` in deploy/crds")),
            Some(schema) => {
                if let Err(e) = resolve(schema, path) {
                    bad.push(format!(
                        "{who}: `{spec_path}` is not in deploy/crds ({e}). Fix: correct the \
                         path, or run `mise run gen` if the field is new"
                    ));
                }
            }
        }
    }
    assert!(bad.is_empty(), "\n{}", bad.join("\n"));
}

/// The CRD lookup itself must reject a path that is not there, or the test
/// above proves nothing.
#[test]
fn resolver_rejects_missing_paths() {
    let schemas = crd_schemas();
    let sp = &schemas["SnapshotPolicy"];
    assert!(resolve(sp, "spec.upload.forceHashPercent").is_ok());
    assert!(resolve(sp, "spec.upload.noSuchField").is_err());
    assert!(resolve(sp, "spec.sources[].pvc").is_ok());
    assert!(Path::new(&fixture_dir()).is_dir());
}
